"""M7.58: Ghidra-informed whole 28-PPC block generated by real CFG lifter."""
from pathlib import Path
import sys
import unittest
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/"tools"))
from generate_m758_owner_aot import PC,END,WORDS,BE_SHA,generate
class M758(unittest.TestCase):
 def test_reused_compiler_lifts_all_original_ppc_words(self):
  c,d=generate()
  self.assertEqual(d['number_words'],28)
  self.assertEqual(d['word_sha256'],BE_SHA)
  self.assertEqual(d['next_pc'],'0x003c51f4')
  self.assertGreaterEqual(d['guest_memory_ops'],4)
  for t in ('ar_m758_native_003c5110','ar_m758_register_owner',
            'ar_m712_exec_window','ar_read32(addr)',
            'if(ar_last_error()!=AR_OK) return AR_MEM_FAULT;',
            'c->cia=0x3c51f4ULL; return 1;'):
   self.assertIn(t,c)
  self.assertNotIn('ar_ppc_fallback_step',c)
  self.assertNotIn('ar_ppc_fallback_attach',c)
  self.assertNotIn('goto L_',c)
  self.assertNotIn('    L_3c',c)
 def test_registered_with_existing_aot_no_interpreter(self):
  b=(ROOT/'ios/ARLivePPUBridge.c').read_text()
  sh=(ROOT/'tools/build_ios_probe_ipa.sh').read_text()
  wf=(ROOT/'.github/workflows/ascension-recomp-m0.yml').read_text()
  self.assertIn('ar_m758_register_owner(d,len)',b)
  self.assertIn('python3 tools/generate_m758_owner_aot.py',sh)
  self.assertIn('ppu_m758_generated.o',sh)
  self.assertIn('_ar_m758_register_owner',sh)
  self.assertIn('host_m758_generated.c',wf)
  self.assertIn('m758-host.log',wf)
  self.assertNotIn('    ios-probe/ppu_m720_fallback.o \\',sh)
 def test_physical_baseline_and_guest_FS_not_fabricated(self):
  b=(ROOT/'ios/ARProbeApp.m').read_text()
  self.assertIn('M7.58 (teste físico',b)
  self.assertIn('M7.58 AOT ONLY atual:',b)
  self.assertIn('cellFsRead com bytes positivos',b)
  self.assertIn('ELF versus RAM guest',b)
if __name__=='__main__':unittest.main()
